-- V12.2 — Glossário Profissional
begin;
create table if not exists public.real_estate_glossary(
 id bigint generated by default as identity primary key,
 term text not null unique, full_name text not null, category text not null,
 language text not null default 'PT', definition text not null,
 portugal_usage text, caution text, related_terms text,
 status text not null default 'published',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
alter table public.real_estate_glossary enable row level security;
drop policy if exists "authenticated read glossary" on public.real_estate_glossary;
create policy "authenticated read glossary" on public.real_estate_glossary for select to authenticated using(status='published' or public.is_admin());
drop policy if exists "admins manage glossary" on public.real_estate_glossary;
create policy "admins manage glossary" on public.real_estate_glossary for all to authenticated using(public.is_admin()) with check(public.is_admin());
on conflict(term) do update set full_name=excluded.full_name,category=excluded.category,language=excluded.language,definition=excluded.definition,portugal_usage=excluded.portugal_usage,caution=excluded.caution,related_terms=excluded.related_terms,status='published',updated_at=now();
commit;