insert into public.real_estate_glossary(term,full_name,category,language,definition,portugal_usage,caution,related_terms) values
('AMI','Licença AMI','Siglas e Regulação','PT','Referência da licença da empresa habilitada a exercer mediação imobiliária.','É a identificação corrente da licença da mediadora.','A licença respeita à empresa de mediação; não é um título profissional individual.','IMPIC; Mediação imobiliária'),
('IMPIC','Instituto dos Mercados Públicos, do Imobiliário e da Construção','Siglas e Regulação','PT','Entidade pública competente, entre outras matérias, pela regulação e fiscalização da mediação imobiliária.','É a entidade de referência para licenciamento da atividade.','Confirmar sempre informação regulatória atual no IMPIC.','AMI; CMI'),
('CMI','Contrato de Mediação Imobiliária','Contratos e Documentos','PT','Contrato escrito entre empresa de mediação e cliente que enquadra o serviço de mediação.','É normalmente chamado simplesmente CMI.','Não é CPCV nem contrato de compra e venda.','Exclusividade; Comissão; CPCV'),
('CPCV','Contrato-Promessa de Compra e Venda','Contratos e Documentos','PT','Contrato pelo qual as partes se comprometem a celebrar futuramente a compra e venda nos termos acordados.','É muito frequente antes do ato definitivo de transmissão.','O conteúdo concreto deve ser analisado; o consultor não deve substituir aconselhamento jurídico.','Sinal; Escritura; DPA'),
('NDA','Non-Disclosure Agreement · Acordo de Confidencialidade','Contratos e Documentos','EN','Acordo destinado a proteger informação confidencial partilhada entre partes.','É comum ouvir “NDA” em investimento, promoção e operações reservadas.','Não é uma proposta, CMI ou CPCV.','LOI; Data Room; Due Diligence'),
('LOI','Letter of Intent · Carta de Intenções','Contratos e Documentos','EN','Documento que organiza intenções ou bases negociais preliminares.','A sigla LOI surge sobretudo em investimento e operações profissionais.','O efeito vinculativo depende da redação concreta.','NDA; MOU; Due Diligence'),
('MOU','Memorandum of Understanding · Memorando de Entendimento','Contratos e Documentos','EN','Documento que regista entendimentos preliminares entre partes.','Mais comum em investimento, promoção e operações empresariais.','O alcance jurídico depende do conteúdo.','LOI; NDA'),
('DPA','Documento Particular Autenticado','Contratos e Documentos','PT','Forma documental usada na formalização de negócios quando legalmente admissível.','Surge frequentemente como alternativa à escritura pública.','Não confundir com documento particular simples.','Escritura; CPCV'),
('CRP','Conservatória do Registo Predial','Siglas e Regulação','PT','Serviço do registo relacionado com a publicidade de factos jurídicos sobre imóveis.','No trabalho diário consulta-se frequentemente a certidão permanente predial.','Matriz e registo predial têm funções distintas.','Certidão permanente; Registo predial'),
('CPU','Caderneta Predial Urbana','Contratos e Documentos','PT','Documento matricial relativo a prédio urbano no âmbito tributário.','Usado para conferir artigo, VPT, áreas e outros elementos matriciais.','Não substitui a certidão predial.','VPT; Artigo matricial'),
('VPT','Valor Patrimonial Tributário','Fiscalidade e Crédito','PT','Valor determinado segundo regras fiscais para efeitos tributários.','Aparece na caderneta predial e é relevante para impostos patrimoniais.','Não equivale necessariamente ao valor de mercado.','IMI; IMT'),
('IMI','Imposto Municipal sobre Imóveis','Fiscalidade e Crédito','PT','Imposto periódico associado à titularidade de imóveis segundo as regras fiscais.','É um custo relevante para proprietários e investidores.','Não confundir com IMT.','VPT; IMT'),
('IMT','Imposto Municipal sobre as Transmissões Onerosas de Imóveis','Fiscalidade e Crédito','PT','Imposto que pode incidir sobre transmissões onerosas de imóveis.','É considerado no orçamento de aquisição.','Taxas e isenções dependem do caso e legislação vigente.','IS; VPT'),
('IS','Imposto do Selo','Fiscalidade e Crédito','PT','Imposto aplicável a atos e operações previstos na lei.','Pode surgir na aquisição e no financiamento.','A incidência varia conforme o ato.','IMT; Crédito'),
('CE','Certificado Energético','Contratos e Documentos','PT','Documento relativo ao desempenho energético do imóvel quando sujeito ao regime aplicável.','É habitual em promoção e transação de imóveis.','Confirmar exclusões ou dispensas aplicáveis.','SCE; Anúncio'),
('FTH','Ficha Técnica da Habitação','Contratos e Documentos','PT','Documento técnico aplicável a determinados edifícios habitacionais segundo o respetivo regime.','Pode integrar a documentação necessária do imóvel.','A aplicabilidade depende do enquadramento temporal e legal.','Licença de utilização'),
('PH','Propriedade Horizontal','Jurídico e Direitos','PT','Regime em que um edifício se divide em frações autónomas e partes comuns.','Central em apartamentos e lojas integrados em condomínio.','Conferir título constitutivo e registo.','Fração autónoma; Condomínio'),
('PDM','Plano Diretor Municipal','Urbanismo e Terrenos','PT','Instrumento municipal que estabelece o quadro de organização e uso do território.','É referência central na análise de terrenos.','Deve ser lido com regulamento, plantas e condicionantes.','PIP; RAN; REN'),
('PIP','Pedido de Informação Prévia','Urbanismo e Terrenos','PT','Procedimento para obter informação ou decisão prévia sobre determinada operação urbanística.','Muito relevante quando o potencial construtivo é determinante.','Não é sinónimo de licença de construção.','PDM; Licenciamento'),
('RJUE','Regime Jurídico da Urbanização e da Edificação','Urbanismo e Terrenos','PT','Regime legal central das operações urbanísticas.','É referência recorrente em licenciamento e urbanismo.','Confirmar sempre a versão vigente.','PIP; Licenciamento'),
('RAN','Reserva Agrícola Nacional','Urbanismo e Terrenos','PT','Regime de proteção de solos com aptidão agrícola.','Pode condicionar usos e operações num terreno.','Não traduzir automaticamente por “não se pode construir”.','REN; PDM'),
('REN','Reserva Ecológica Nacional','Urbanismo e Terrenos','PT','Estrutura de proteção territorial sujeita a regime próprio.','É condicionante relevante na due diligence de terrenos.','A viabilidade exige análise concreta.','RAN; PDM'),
('ARU','Área de Reabilitação Urbana','Urbanismo e Terrenos','PT','Área delimitada para enquadrar políticas e intervenções de reabilitação urbana.','Pode ser relevante para procedimentos e incentivos.','ARU e ORU não são sinónimos.','ORU; Reabilitação'),
('ORU','Operação de Reabilitação Urbana','Urbanismo e Terrenos','PT','Conjunto articulado de intervenções de reabilitação urbana enquadradas no regime aplicável.','Surge frequentemente associada a uma ARU.','Confirmar âmbito e vigência.','ARU'),
('Lead','Lead · contacto/oportunidade potencial','Prospecção e Comercial','EN','Pessoa ou entidade identificada como potencial oportunidade comercial.','“Lead” é muito usado por equipas comerciais em Portugal.','Um lead não é necessariamente cliente qualificado.','Prospect; Pipeline'),
('Prospect','Prospect · potencial cliente qualificado','Prospecção e Comercial','EN','Contacto com potencial que justifica acompanhamento comercial dirigido.','Algumas equipas distinguem prospect de lead pelo grau de qualificação.','Convém definir critérios internos.','Lead; Qualificação'),
('Cold Lead','Cold lead · contacto frio','Prospecção e Comercial','EN','Contacto sem relação recente ou sinal forte de intenção.','Usado em CRM e prospeção.','Não significa ausência absoluta de potencial.','Warm lead'),
('Warm Lead','Warm lead · contacto morno/quente','Prospecção e Comercial','EN','Contacto que já demonstrou interesse ou interação relevante.','Expressão comum em vendas.','Os critérios variam entre equipas.','Hot lead; Follow-up'),
('Hot Lead','Hot lead · contacto prioritário','Prospecção e Comercial','EN','Contacto com intenção ou probabilidade comercial elevada no curto prazo.','Usado para priorização comercial.','Não garante concretização do negócio.','Closing'),
('Cold Calling','Cold calling · prospeção telefónica a frio','Prospecção e Comercial','EN','Contacto telefónico comercial iniciado sem relação recente.','É usado em prospeção imobiliária.','Deve respeitar regras aplicáveis a comunicações e dados pessoais.','Lead; RGPD'),
('Follow-up','Follow-up · acompanhamento','Prospecção e Comercial','EN','Retoma de contacto após reunião, visita, proposta ou interação.','É uma expressão muito corrente nas equipas.','Deve ter contexto e próximo passo.','Pipeline; CRM'),
('Farming','Geographic farming · prospeção de zona','Prospecção e Comercial','EN','Estratégia de concentração comercial numa área ou segmento.','Usado por várias redes e equipas.','É linguagem comercial, não conceito jurídico.','Prospeção; Lead'),
('Referral','Referral · referência/recomendação','Prospecção e Comercial','EN','Contacto ou oportunidade proveniente de recomendação.','Comum em redes e equipas internacionais.','Distinguir recomendação de acordo comercial formal.','Lead; Networking'),
('Pipeline','Pipeline comercial','Prospecção e Comercial','EN','Representação das oportunidades pelas fases do processo comercial.','Normalmente gerido no CRM.','Não equivale a faturação garantida.','CRM; Closing'),
('CRM','Customer Relationship Management','Siglas e Regulação','EN','Sistema/processo de gestão de contactos, clientes e oportunidades.','Usado para leads, imóveis, visitas e tarefas.','O tratamento de dados deve respeitar o RGPD.','Pipeline; Lead'),
('Closing','Closing · fecho','Prospecção e Comercial','EN','Fase de fecho comercial de uma negociação.','Em equipas internacionais pode também referir o momento formal da transação.','Em Portugal deve identificar-se o ato jurídico concreto.','Escritura; DPA'),
('Listing','Listing · imóvel em carteira','Prospecção e Comercial','EN','Termo comercial para imóvel colocado em comercialização.','Ouve-se “listing”, “angariação” e “imóvel em carteira”.','Não é equivalente jurídico exato de CMI.','Angariação; CMI'),
('Off-market','Off-market','Prospecção e Comercial','EN','Imóvel ou operação promovida sem divulgação pública ampla.','Comum em luxo, investimento e operações reservadas.','Não elimina obrigações legais ou contratuais.','NDA; Due Diligence'),
('Open House','Open house · visita aberta','Prospecção e Comercial','EN','Evento de visita a um imóvel durante período definido.','A expressão é usada no mercado português.','Respeitar instruções do proprietário, segurança e dados.','Visita; Lead'),
('Home Staging','Home staging','Marketing Imobiliário','EN','Preparação estética e funcional do imóvel para apresentação comercial.','Pode envolver organização, decoração e iluminação.','Não é avaliação nem regularização do imóvel.','Marketing; Fotografia'),
('Buyer’s Agent','Buyer’s agent · consultor do comprador','Intervenientes','EN','Profissional orientado para acompanhar a procura/comprador segundo o modelo contratual adotado.','Surge em serviços dedicados ao comprador e redes internacionais.','Importa identificar quem é o cliente contratual da mediadora.','Cliente; Mediadora'),
('Developer','Developer · promotor imobiliário','Intervenientes','EN','Entidade que estrutura e promove o desenvolvimento de um projeto imobiliário.','“Developer” é muito ouvido em promoção e investimento em Portugal.','Não é automaticamente construtor ou vendedor.','Promotor; Construtor'),
('Promotor Imobiliário','Promotor imobiliário','Intervenientes','PT','Entidade que promove ou desenvolve uma operação/projeto imobiliário.','Muito relevante em empreendimentos e produto novo.','Não confundir automaticamente com construtor, vendedor ou mediadora.','Developer; Construtor'),
('Proprietário','Proprietário','Intervenientes','PT','Titular do direito de propriedade sobre o imóvel.','Na angariação deve confirmar-se capacidade e legitimidade.','Quem apresenta o imóvel pode não ser o único proprietário.','Vendedor; Usufruto'),
('Vendedor','Vendedor','Intervenientes','PT','Parte que assume a posição de alienante numa compra e venda.','Pode coincidir com o proprietário.','Não é sinónimo automático de promotor.','Proprietário; Promotor'),
('Construtor','Construtor','Intervenientes','PT','Entidade ligada à execução da atividade de construção.','Em produto novo pode ser diferente do promotor e vendedor.','Confirmar papéis concretos no projeto.','Promotor; Empreiteiro'),
('Empreiteiro','Empreiteiro','Intervenientes','PT','Entidade contratada para executar uma obra ou empreitada.','Pode trabalhar para promotor ou proprietário.','Não é necessariamente promotor.','Construtor'),
('Mediadora','Empresa de mediação imobiliária','Intervenientes','PT','Empresa habilitada que exerce mediação imobiliária mediante contrato.','É a entidade contratual sujeita ao regime da mediação.','Distinguir empresa do consultor individual.','AMI; CMI'),
('Consultor Imobiliário','Consultor imobiliário','Intervenientes','PT','Designação comercial corrente do profissional que acompanha clientes e operações no âmbito da mediadora.','É a expressão mais comum no mercado.','Não confundir a pessoa com a empresa licenciada.','Mediadora'),
('Angariação','Angariação','Prospecção e Comercial','PT','Processo comercial de obtenção de cliente/imóvel para mediação e preparação da comercialização.','Inclui qualificação e recolha de informação.','Não substitui a formalização contratual exigível.','CMI; Listing'),
('Prospeção','Prospeção','Prospecção e Comercial','PT','Ações destinadas a identificar oportunidades, clientes ou imóveis.','A legislação da mediação inclui ações de prospeção e recolha de informação.','Respeitar regras de comunicações e dados.','Lead; Farming'),
('Exclusividade','Regime/cláusula de exclusividade','Contratos e Documentos','PT','Cláusula do CMI que define efeitos específicos quanto à mediação do negócio.','É frequente em angariação.','Os efeitos concretos devem resultar do contrato; não simplificar em excesso.','CMI; Comissão'),
('Comissão','Remuneração da mediadora','Prospecção e Comercial','PT','Remuneração acordada pela prestação de mediação nas condições do CMI.','No discurso comercial é comum dizer “comissão”.','A exigibilidade depende do contrato e do regime legal.','CMI; Exclusividade'),
('Due Diligence','Due diligence · verificação prévia','Contratos e Documentos','EN','Processo estruturado de verificação de informação, documentos e riscos antes de uma decisão.','Muito usado em investimento e operações profissionais.','Não é um único documento nem garante ausência de risco.','Data Room; NDA'),
('Data Room','Data room · repositório documental','Contratos e Documentos','EN','Espaço físico ou digital organizado para documentação de uma operação.','Comum em investimento e ativos comerciais.','O acesso pode estar sujeito a NDA.','NDA; Due Diligence'),
('KYC','Know Your Customer','Siglas e Regulação','EN','Procedimentos de identificação e conhecimento do cliente em contexto de compliance.','Sigla comum em banca, investimento e conformidade.','Não reduzir KYC à recolha de um documento de identificação.','AML; PEP'),
('AML','Anti-Money Laundering · prevenção do branqueamento de capitais','Siglas e Regulação','EN','Expressão internacional para políticas e controlos de prevenção do branqueamento.','Usada em compliance imobiliário.','Seguir obrigações legais e procedimentos aplicáveis em Portugal.','KYC; PEP'),
('PEP','Politically Exposed Person · pessoa politicamente exposta','Siglas e Regulação','EN','Categoria relevante em procedimentos de prevenção do branqueamento.','A sigla é usada internacionalmente e em Portugal.','A classificação deve seguir critérios legais, não intuição.','AML; KYC'),
('RGPD','Regulamento Geral sobre a Proteção de Dados','Siglas e Regulação','PT','Regime europeu aplicável ao tratamento de dados pessoais.','Relevante em leads, CRM, marketing e documentação.','Ter um contacto não autoriza qualquer utilização dos dados.','CRM; Consentimento'),
('ROI','Return on Investment · retorno do investimento','Investimento','EN','Indicador que relaciona retorno e investimento segundo uma fórmula definida.','Usado para comparar investimentos.','Não confundir com yield.','Yield; Cap rate'),
('Yield','Yield · rentabilidade/rendimento','Investimento','EN','Medida de rendimento de um ativo face ao seu preço ou valor, conforme metodologia.','Muito usada em investimento e arrendamento.','Distinguir yield bruta e líquida.','ROI; NOI'),
('Cap Rate','Capitalization Rate · taxa de capitalização','Investimento','EN','Indicador que relaciona rendimento operacional e valor do ativo segundo a metodologia adotada.','Mais comum em ativos de rendimento e investimento profissional.','Não é sinónimo automático de yield bruta.','NOI; Yield'),
('NOI','Net Operating Income · rendimento operacional líquido','Investimento','EN','Métrica de rendimento operacional líquido segundo os custos considerados.','Comum em análise internacional de ativos de rendimento.','Explicitar sempre que despesas entram no cálculo.','Cap Rate; Yield'),
('LTV','Loan-to-Value','Fiscalidade e Crédito','EN','Rácio entre financiamento e valor de referência do imóvel usado pelo financiador.','Linguagem corrente no crédito imobiliário.','Critérios dependem da instituição e regras aplicáveis.','DSTI; Crédito'),
('DSTI','Debt Service-to-Income','Fiscalidade e Crédito','EN','Rácio entre encargos de dívida e rendimento segundo critérios prudenciais.','Usado na análise de capacidade financeira.','Não garante aprovação do crédito.','LTV; Taxa de esforço'),
('TAEG','Taxa Anual de Encargos Efetiva Global','Fiscalidade e Crédito','PT','Indicador do custo total do crédito expresso em percentagem anual segundo regras próprias.','Ajuda a comparar propostas comparáveis.','Não confundir com TAN.','TAN; MTIC'),
('TAN','Taxa Anual Nominal','Fiscalidade e Crédito','PT','Taxa nominal de juros do crédito.','Surge nas propostas de financiamento.','Não inclui todos os encargos refletidos na TAEG.','TAEG; MTIC'),
('MTIC','Montante Total Imputado ao Consumidor','Fiscalidade e Crédito','PT','Montante total a pagar pelo consumidor no crédito segundo as regras aplicáveis.','Ajuda a perceber o custo global.','Analisar com prazo, TAEG e condições.','TAEG; TAN'),
('Lote','Lote','Urbanismo e Terrenos','PT','Unidade predial resultante, designadamente, de operação de loteamento conforme o caso.','É importante distinguir lote de parcela.','Não chamar lote a qualquer terreno sem verificar.','Loteamento; Parcela'),
('Parcela','Parcela','Urbanismo e Terrenos','PT','Porção de terreno identificada em determinado contexto cadastral, urbanístico ou negocial.','O sentido depende do documento/procedimento.','Não é automaticamente sinónimo de lote.','Lote; Prédio'),
('Loteamento','Operação de loteamento','Urbanismo e Terrenos','PT','Operação urbanística de divisão de prédios em lotes destinados à edificação nos termos aplicáveis.','Central na análise de urbanizações.','Conferir título e condições concretas.','Lote; Infraestruturas'),
('Área Bruta Privativa','Área bruta privativa','Urbanismo e Terrenos','PT','Conceito de área usado, nomeadamente, no contexto matricial/fiscal.','Frequente em cadernetas e anúncios.','Não tratar automaticamente como área útil.','Área útil; CPU'),
('Área Bruta Dependente','Área bruta dependente','Urbanismo e Terrenos','PT','Conceito matricial/fiscal associado a áreas acessórias segundo a definição aplicável.','Surge na caderneta predial.','Não interpretar sem conhecer a fonte.','Área bruta privativa'),
('Área Útil','Área útil','Urbanismo e Terrenos','PT','Área dos espaços utilizáveis segundo o conceito técnico/legal aplicável.','Muito usada comercialmente.','Documentos e plataformas podem usar metodologias distintas.','Área bruta'),
('Área de Implantação','Área de implantação','Urbanismo e Terrenos','PT','Área da projeção da edificação no terreno segundo o conceito aplicável.','Usada em parâmetros urbanísticos.','Não confundir com área total de construção.','Área de construção'),
('Área de Construção','Área de construção','Urbanismo e Terrenos','PT','Área de pavimentos/construção calculada segundo regras do instrumento aplicável.','Essencial na edificabilidade.','Confirmar definição municipal aplicável.','PDM; Índice'),
('Índice de Construção','Índice de construção/utilização','Urbanismo e Terrenos','PT','Parâmetro que relaciona área de construção com uma área de referência.','Usado na análise de capacidade edificatória.','Nunca analisar isoladamente das restantes regras.','PDM; Área de construção'),
('Cércea','Cércea','Urbanismo e Terrenos','PT','Parâmetro relacionado com a dimensão vertical da edificação segundo definição urbanística aplicável.','Surge em regulamentos e estudos urbanísticos.','Confirmar definição usada pelo município.','PDM; Altura'),
('Servidão','Servidão predial / administrativa','Jurídico e Direitos','PT','Limitação ou encargo que pode afetar um prédio, de natureza privada ou administrativa.','Pode ser decisiva para acessos e edificabilidade.','Identificar o tipo e o respetivo título/regime.','Ónus; Acesso'),
('Usufruto','Usufruto','Jurídico e Direitos','PT','Direito real de uso e fruição de bem pertencente a outrem dentro dos limites legais.','Pode afetar a venda e quem deve intervir.','Proprietário e usufrutuário têm posições distintas.','Nua-propriedade'),
('Nua-propriedade','Nua-propriedade','Jurídico e Direitos','PT','Posição do proprietário quando o gozo do bem se encontra limitado por usufruto.','Surge em transmissões familiares e heranças.','Não confundir com propriedade plena.','Usufruto'),
('Hipoteca','Hipoteca','Jurídico e Direitos','PT','Garantia real que pode incidir sobre imóvel para assegurar obrigação.','É frequente em imóveis financiados.','Não significa por si só impossibilidade de venda.','Distrate; Ónus'),
('Penhora','Penhora','Jurídico e Direitos','PT','Apreensão jurídica de bens no âmbito de processo executivo.','É alerta relevante na due diligence.','Não confundir com hipoteca.','Ónus; Registo'),
('Distrate','Distrate/cancelamento de garantia','Contratos e Documentos','PT','Expressão corrente associada à extinção/cancelamento de garantia, frequentemente hipoteca.','Surge em vendas com crédito existente.','Confirmar procedimento concreto com entidade competente.','Hipoteca'),
('Direito de Preferência','Direito de preferência','Jurídico e Direitos','PT','Direito que em certas situações permite a alguém preferir na aquisição em condições definidas.','Pode exigir comunicações ou procedimentos prévios.','A existência depende do caso concreto.','Arrendamento; Município'),
('Sinal','Sinal','Contratos e Documentos','PT','Prestação entregue no contexto contratual com os efeitos resultantes da lei e do contrato.','Muito associado ao CPCV.','Não chamar sinal a qualquer reserva ou adiantamento.','CPCV; Reserva'),
('Reserva','Reserva de imóvel','Contratos e Documentos','PT','Designação comercial para mecanismos de manifestação de interesse ou retirada temporária do mercado.','É frequente antes do CPCV.','Os efeitos dependem do documento; reserva não é CPCV.','Sinal; CPCV'),
('Escritura','Escritura pública','Contratos e Documentos','PT','Instrumento público usado na formalização de atos e negócios.','“A escritura” é expressão corrente para o fecho formal da compra e venda.','Existem outras formas legalmente admissíveis, como DPA.','DPA; CPCV'),
('Fração Autónoma','Fração autónoma','Jurídico e Direitos','PT','Unidade independente de prédio constituído em propriedade horizontal.','É normalmente a unidade transacionada em apartamentos e lojas em PH.','Não confundir com o prédio inteiro.','PH; Condomínio'),
('Permilagem','Permilagem','Jurídico e Direitos','PT','Proporção atribuída à fração no contexto da propriedade horizontal, normalmente por mil.','Relevante no condomínio.','Não é simples percentagem da área física.','PH; Condomínio'),
('Condomínio','Condomínio','Jurídico e Direitos','PT','Organização das relações entre condóminos e partes comuns em propriedade horizontal.','Na due diligence interessam encargos e deliberações relevantes.','Administrador não é proprietário das frações.','PH; Permilagem'),
('Yield Bruta','Gross yield · yield bruta','Investimento','EN','Rácio simples entre renda anual bruta e preço/valor de referência.','Muito usado em anúncios de investimento.','Não considera necessariamente despesas, vacância ou impostos.','Yield líquida; ROI'),
('Yield Líquida','Net yield · yield líquida','Investimento','EN','Indicador de rentabilidade após dedução das despesas definidas na metodologia.','Mais informativo quando os custos são claros.','Explicitar os custos considerados.','Yield bruta; NOI'),
('Flip','Property flip / flipping','Investimento','EN','Estratégia de comprar, valorizar e revender num horizonte relativamente curto.','Usado por investidores e conteúdos de mercado.','Considerar obras, impostos, financiamento, venda e risco.','ROI; Reabilitação'),
('Buy-to-let','Buy-to-let','Investimento','EN','Aquisição de imóvel com objetivo principal de arrendamento.','Expressão internacional também usada por profissionais em Portugal.','Considerar fiscalidade, custos e vacância.','Yield; Arrendamento'),
('Turnkey','Turnkey · chave na mão','Marketing Imobiliário','EN','Expressão para imóvel/projeto entregue pronto a utilizar segundo o âmbito contratado.','Comum em promoção e reabilitação.','Não define sozinho acabamentos ou mobiliário incluído.','Promotor; Empreitada'),
